import { observer } from "mobx-react";
import { createContext, forwardRef, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useSDK } from "../../../providers/SDKProvider";
import { isDefined } from "../../../utils/utils";
import { modal } from "../Modal/Modal";
import { BracketsCurlyIcon } from "@humansignal/icons";
import { AutoSizerTable, Button, useContextMenu } from "@humansignal/ui";
import "./Table.prefix.css";
import { TableCheckboxCell } from "./TableCheckbox";
import { tableCN, TableContext } from "./TableContext";
import { TableHead } from "./TableHead/TableHead";
import { TableRow } from "./TableRow/TableRow";
import { RowContextMenu } from "./RowContextMenu";
import { prepareColumns } from "./utils";
import { cn } from "../../../utils/bem";
import { FieldsButton } from "../FieldsButton";
import { FF_LOPS_E_3, isFF } from "../../../utils/feature-flags";
import {
  FF_DM_SHARED_COLUMN_ORDER,
  FF_PROJECT_DM_COLUMN_DEFAULTS,
  isActive,
} from "@humansignal/core/lib/utils/feature-flags";
import { DensityToggle } from "../../DataManager/Toolbar/DensityToggle";
import { TaskSourceViewer, getTaskSourceViewerStorageKey } from "../TaskSourceViewer";
import {
  readPersonalColumnOrder,
  persistPersonalColumnOrderIfNeeded,
  onPersonalColumnOrderCleared,
  resolveEffectiveColumnOrder,
} from "./columnOrderStorage";

const Decorator = (decoration) => {
  return {
    get(col) {
      return decoration.find((d) => {
        let found = false;

        if (isDefined(d.alias)) {
          found = d.alias === col.alias;
        } else if (d.resolver instanceof Function) {
          found = d.resolver(col);
        }

        return found;
      });
    },
  };
};

export const Table = observer(
  ({
    view,
    data,
    cellViews,
    selectedItems,
    focusedItem,
    decoration,
    stopInteractions,
    stopRowInteractions = stopInteractions,
    onColumnResize,
    onColumnReset,
    headerExtra,
    onDensityChange,
    onRangeSelect,
    onViewAnalytics,
    onViewReviewerAnalytics,
    RowContextMenuComponent,
    ...props
  }) => {
    const tableHead = useRef();
    const sharedColumnOrder = isActive(FF_DM_SHARED_COLUMN_ORDER);
    const projectColumnDefaults = isActive(FF_PROJECT_DM_COLUMN_DEFAULTS);
    const [localColOrder, setLocalColOrder] = useState(() => (sharedColumnOrder ? {} : readPersonalColumnOrder()));
    // When shared-tab order is off, personal browser prefs win only for columns on this view.
    // Tab columnOrder fallback is gated on FF_PROJECT_DM_COLUMN_DEFAULTS so older tabs that
    // already persisted columnOrder (from shared-order era) do not suddenly apply when both
    // FFs are off (FIT-2846 review).
    const tabColumnOrder = view?.columnOrderSnapshot ?? {};
    const columnIds = (view?.columns ?? []).map((c) => c?.id).filter(Boolean);
    const colOrder = resolveEffectiveColumnOrder({
      sharedColumnOrder,
      projectColumnDefaults,
      personalOrder: localColOrder,
      tabColumnOrder,
      columnIds,
    });

    useEffect(() => {
      if (sharedColumnOrder) return undefined;
      return onPersonalColumnOrderCleared((next) => setLocalColOrder(next ?? {}));
    }, [sharedColumnOrder]);
    const listRef = useRef();
    const Decoration = useMemo(() => Decorator(decoration), [decoration]);
    const { api, type, projectId } = useSDK();
    const toolbarHeight = 41;
    const isQuickView = view.root.isLabeling;
    const [toolbarVisible, setToolbarVisible] = useState(true);
    // Track last clicked row ID for shift-click range selection
    const lastClickedId = useRef(null);

    // Table-level context menu state (DM-local: x/y + row + column).
    // Positioning/open/close lives in useContextMenu; domain payload stays here.
    const [contextMenu, setContextMenu] = useState(null);
    const pendingContextRowRef = useRef(null);
    // Maintain hover appearance on row while its context menu is open for better visual feedback
    const contextMenuRowId = contextMenu?.row?.id ?? null;

    // Reset virtualizer cache when rowHeight changes
    useEffect(() => {
      if (listRef.current?._listRef) {
        listRef.current._listRef.resetAfterIndex(0);
      }
    }, [props.rowHeight]);

    const headerCheckboxCell = useCallback(() => {
      return (
        <TableCheckboxCell
          checked={selectedItems.isAllSelected}
          indeterminate={selectedItems.isIndeterminate}
          onChange={() => props.onSelectAll()}
          className="select-all"
          ariaLabel={`${selectedItems.isAllSelected ? "Unselect" : "Select"} all rows`}
        />
      );
    }, [props.onSelectAll, selectedItems]);

    const rowCheckBoxCell = useCallback(
      ({ data: rowData }) => {
        const isChecked = selectedItems.isSelected(rowData.id);
        return (
          <TableCheckboxCell
            checked={isChecked}
            onChange={(checked, shiftKey) => {
              // Handle shift-click for range selection (works for both select and unselect)
              if (shiftKey && lastClickedId.current !== null && onRangeSelect) {
                const lastClickedIndex = data.findIndex((item) => item.id === lastClickedId.current);
                const currentIndex = data.findIndex((item) => item.id === rowData.id);

                if (lastClickedIndex !== -1 && currentIndex !== -1) {
                  const startIndex = Math.min(lastClickedIndex, currentIndex);
                  const endIndex = Math.max(lastClickedIndex, currentIndex);
                  const rangeIds = data.slice(startIndex, endIndex + 1).map((item) => item.id);

                  // Pass the select state: true = select range, false = unselect range
                  onRangeSelect(rangeIds, checked);
                  lastClickedId.current = rowData.id;
                  return;
                }
              }

              // Normal single-item toggle
              props.onSelectRow(rowData.id);
              // Always remember last clicked for shift-click range
              lastClickedId.current = rowData.id;
            }}
            ariaLabel={`${isChecked ? "Unselect" : "Select"} Task ${rowData.id}`}
          />
        );
      },
      [props.onSelectRow, selectedItems, data, onRangeSelect],
    );

    const columns = prepareColumns(props.columns, props.hiddenColumns);

    columns.unshift({
      id: "select",
      headerClassName: "table__select-all",
      cellClassName: "select-row",
      style: {
        width: 40,
        maxWidth: 40,
        justifyContent: "center",
      },
      onClick: (e) => e.stopPropagation(),
      Header: headerCheckboxCell,
      Cell: rowCheckBoxCell,
    });

    columns.push({
      id: "show-source",
      cellClassName: "show-source",
      headerClassName: "show-source",
      style: {
        width: 44,
        maxWidth: 44,
        justifyContent: "center",
      },
      onClick: (e) => e.stopPropagation(),
      Header() {
        return <div style={{ width: 44 }} />;
      },
      Cell({ data }) {
        let out = JSON.parse(data.source ?? "{}");

        out = {
          id: out?.id,
          data: out?.data,
          annotations: out?.annotations,
          predictions: out?.predictions,
        };

        const onTaskLoad = async (options = {}) => {
          if (isFF(FF_LOPS_E_3) && type === "DE") {
            return new Promise((resolve) => resolve(out));
          }
          const response = await api.task({
            taskID: out.id,
            resolve_uri: options.resolveUri ?? false,
          });

          return response ?? {};
        };

        return (
          <Button
            look="string"
            className="w-6 p-0 text-primary-content hover:text-primary-content-hover"
            onClick={() => {
              const modalInstance = modal({
                title: `Source for task ${out?.id}`,
                style: { width: 900 },
                header: null, // Will be set by renderToggle
                body: (
                  <TaskSourceViewer
                    content={out}
                    onTaskLoad={onTaskLoad}
                    sdkType={type}
                    storageKey={getTaskSourceViewerStorageKey(projectId)}
                    renderToggle={(toggle) => {
                      // Update modal header with toggle
                      modalInstance?.update({ header: toggle });
                    }}
                  />
                ),
              });
            }}
            leading={<BracketsCurlyIcon size={20} className="w-5 h-5 shrink-0" />}
            tooltip="View Task Source"
            data-testid="view-task-source"
          />
        );
      },
    });

    if (Object.keys(colOrder).length > 0) {
      columns.sort((a, b) => {
        return colOrder[a.id] < colOrder[b.id] ? -1 : 1;
      });
    }
    useEffect(() => {
      // Personal browser order only when shared-tab order is off (FIT-2882).
      persistPersonalColumnOrderIfNeeded(sharedColumnOrder, localColOrder);
    }, [localColOrder, sharedColumnOrder]);

    // Store columns in a ref to avoid recreating context-menu open handler
    const columnsRef = useRef(columns);
    columnsRef.current = columns;

    const MenuComponent = RowContextMenuComponent || RowContextMenu;

    const closeContextMenu = useCallback(() => {
      setContextMenu(null);
      pendingContextRowRef.current = null;
    }, []);

    const handleContextMenuOpenChange = useCallback(
      (open) => {
        if (!open) closeContextMenu();
      },
      [closeContextMenu],
    );

    const handleContextMenuOpen = useCallback((event, position) => {
      // Column lookup stays in DM — primitive stays table-agnostic.
      const target = event.target;
      const cell = target instanceof Element ? target.closest(".lsf-table__cell") : null;
      const cellIndex = cell?.parentElement ? Array.from(cell.parentElement.children).indexOf(cell) : -1;
      const column = cellIndex >= 0 ? columnsRef.current[cellIndex] : null;

      setContextMenu({
        x: position.x,
        y: position.y,
        row: pendingContextRowRef.current,
        column,
      });
    }, []);

    // Stable content identity while the menu is open — Table is a MobX observer and
    // re-renders often; a fresh JSX tree each tick remounts Dropdown (flicker / lost clicks).
    // Clearing contextMenu flips controlled `open` false; no need to also call hook.close().
    const contextMenuContent = useMemo(() => {
      if (!contextMenu?.row) return null;

      return (
        <MenuComponent
          row={contextMenu.row}
          column={contextMenu.column}
          view={view}
          api={api}
          sdkType={type}
          projectId={projectId}
          onViewAnalytics={onViewAnalytics}
          onViewReviewerAnalytics={onViewReviewerAnalytics}
          onClose={closeContextMenu}
        />
      );
    }, [
      MenuComponent,
      api,
      closeContextMenu,
      contextMenu,
      onViewAnalytics,
      onViewReviewerAnalytics,
      projectId,
      type,
      view,
    ]);

    const contextMenuPosition = useMemo(
      () => (contextMenu ? { x: contextMenu.x, y: contextMenu.y } : null),
      [contextMenu],
    );

    const { getTriggerProps, menu: contextMenuPortal } = useContextMenu({
      open: Boolean(contextMenu),
      position: contextMenuPosition,
      onOpenChange: handleContextMenuOpenChange,
      onOpen: handleContextMenuOpen,
      content: contextMenuContent,
    });

    // Stable across open/close so StickyList's row Renderer identity does not
    // change (changing Renderer remounts rows → avatar flicker).
    const getRowContextMenuTriggerProps = useCallback(
      (row) =>
        getTriggerProps({
          onContextMenu: () => {
            pendingContextRowRef.current = row;
          },
          onKeyDown: () => {
            pendingContextRowRef.current = row;
          },
        }),
      [getTriggerProps],
    );

    const contextValue = useMemo(
      () => ({
        columns,
        data,
        cellViews,
        contextMenuRowId,
      }),
      [columns, data, cellViews, contextMenuRowId],
    );

    const headerHeight = 43;

    const renderTableToolbar = useCallback(() => {
      return (
        <div className={cn("table-toolbar").mod({ visible: toolbarVisible }).toClassName()}>
          <FieldsButton
            multiSelect={true}
            title={"Columns"}
            size="small"
            tooltip={"Customize Columns"}
            data-testid="columns-picker-quickview"
          />
          <DensityToggle size="small" onChange={onDensityChange} data-testid="density-toggle-quickview" />
        </div>
      );
    }, [toolbarVisible, onDensityChange]);

    const renderTableHeader = useCallback(
      ({ style }) => (
        <TableHead
          ref={tableHead}
          style={style}
          order={props.order}
          columnHeaderExtra={props.columnHeaderExtra}
          sortingEnabled={props.sortingEnabled}
          onSetOrder={props.onSetOrder}
          stopInteractions={stopInteractions}
          onTypeChange={props.onTypeChange}
          decoration={Decoration}
          onResize={onColumnResize}
          onReset={onColumnReset}
          extra={headerExtra}
          onDragEnd={(updatedColOrder) => {
            if (sharedColumnOrder) {
              view.setColumnOrder(updatedColOrder);
              return;
            }
            setLocalColOrder(updatedColOrder);
          }}
        />
      ),
      [
        props.order,
        props.columnHeaderExtra,
        props.sortingEnabled,
        props.onSetOrder,
        props.onTypeChange,
        stopInteractions,
        sharedColumnOrder,
        view,
        view.selected.list,
        view.selected.all,
        tableHead,
      ],
    );

    const renderRow = useCallback(
      ({ style, index }) => {
        // Both QuickView and Regular mode: Index 0 is header (sticky), Index 1+ are data rows
        const dataIndex = index - 1;
        const row = data[dataIndex];
        const isEven = dataIndex % 2 === 0;
        const contextMenuTriggerProps = getRowContextMenuTriggerProps(row);

        if (isQuickView) {
          return (
            <TableRow
              key={row.id}
              data={row}
              even={isEven}
              onClick={(row, e) => props.onRowClick(row, e)}
              stopInteractions={stopRowInteractions}
              wrapperStyle={{ ...style, height: props.rowHeight }}
              style={{
                height: props.rowHeight,
                width: props.fitContent ? "fit-content" : "auto",
              }}
              decoration={Decoration}
              contextMenuTriggerProps={contextMenuTriggerProps}
            />
          );
        }

        // Invert for visual consistency in Regular mode: we want odd rows (2nd, 4th, etc.) to have background
        const shouldApplyBackground = !isEven;

        return (
          <TableRow
            key={row.id}
            data={row}
            even={shouldApplyBackground}
            onClick={(row, e) => props.onRowClick(row, e)}
            stopInteractions={stopRowInteractions}
            wrapperStyle={{ ...style, height: props.rowHeight }}
            style={{
              height: props.rowHeight,
              width: props.fitContent ? "fit-content" : "auto",
            }}
            decoration={Decoration}
            contextMenuTriggerProps={contextMenuTriggerProps}
          />
        );
      },
      [
        data,
        props.fitContent,
        props.onRowClick,
        props.rowHeight,
        stopRowInteractions,
        selectedItems,
        view,
        view.selected.list,
        view.selected.all,
        isQuickView,
        Decoration,
        getRowContextMenuTriggerProps,
      ],
    );

    const isItemLoaded = useCallback(
      (index) => {
        return props.isItemLoaded(data, index);
      },
      [props, data],
    );

    const cachedScrollOffset = useRef();

    const initialScrollOffset = useCallback(
      (height) => {
        if (isDefined(cachedScrollOffset.current)) {
          return cachedScrollOffset.current;
        }

        const h = props.rowHeight;
        const index = data.indexOf(focusedItem);

        if (index >= 0) {
          const scrollOffset = index * h - height / 2 + h / 2; // + headerHeight

          return (cachedScrollOffset.current = scrollOffset);
        }
        return 0;
      },
      [props.rowHeight, data, focusedItem],
    );

    const itemKey = useCallback(
      (index) => {
        if (index > data.length - 1) {
          return index;
        }
        return data[index]?.key ?? index;
      },
      [data],
    );

    useEffect(() => {
      const listComponent = listRef.current?._listRef;

      if (listComponent) {
        listComponent.scrollToItem(data.indexOf(focusedItem), "center");
      }
    }, [data]);
    const tableWrapper = useRef();

    const handleScroll = useCallback(
      ({ scrollOffset }) => {
        if (isQuickView && scrollOffset >= 0) {
          setToolbarVisible(scrollOffset === 0);
        }
      },
      [isQuickView, toolbarHeight],
    );

    return (
      <>
        <div ref={tableWrapper} className={tableCN.mod({ fit: props.fitToContent }).toClassName()}>
          {isQuickView && renderTableToolbar()}
          <TableContext.Provider value={contextValue}>
            <StickyList
              ref={listRef}
              overscanCount={10}
              itemHeight={props.rowHeight}
              totalCount={props.total}
              itemCount={data.length + 1}
              itemKey={itemKey}
              innerElementType={innerElementType}
              stickyItems={[0]}
              stickyItemsHeight={[headerHeight]}
              stickyComponent={renderTableHeader}
              initialScrollOffset={initialScrollOffset}
              isItemLoaded={isItemLoaded}
              loadMore={props.loadMore}
              toolbarHeight={toolbarHeight}
              headerHeight={headerHeight}
              isQuickView={isQuickView}
              onScroll={handleScroll}
              toolbarVisible={toolbarVisible}
            >
              {renderRow}
            </StickyList>
          </TableContext.Provider>
        </div>
        {contextMenuPortal}
      </>
    );
  },
);

const StickyListContext = createContext();

StickyListContext.displayName = "StickyListProvider";

const ItemWrapper = ({ data, index, style }) => {
  const { Renderer, stickyItems } = data;

  if (stickyItems?.includes(index) === true) {
    return null;
  }

  return <Renderer index={index} style={style} />;
};

const StickyList = observer(
  forwardRef((props, listRef) => {
    const {
      children,
      stickyComponent,
      stickyItems,
      stickyItemsHeight,
      totalCount,
      isItemLoaded,
      loadMore,
      initialScrollOffset,
      toolbarHeight,
      headerHeight,
      isQuickView,
      onScroll,
      headerTopOffset,
      toolbarVisible,
      ...rest
    } = props;

    const itemData = {
      Renderer: children,
      StickyComponent: stickyComponent,
      stickyItems,
      stickyItemsHeight,
      headerTopOffset,
      isQuickView,
      toolbarHeight,
    };

    const itemSize = (index) => {
      if (isQuickView) {
        if (stickyItems.includes(index)) {
          return headerHeight;
        }
      } else {
        // Regular mode: Index 0 is sticky header
        if (stickyItems.includes(index)) {
          return headerHeight;
        }
      }
      // All other indices are data rows
      return rest.itemHeight;
    };

    // Calculate height adjustment for QuickView mode
    // Subtract toolbar height (when visible) and app header height
    const heightAdjustment = useMemo(() => {
      if (!isQuickView) return 0;

      // Get app header height from CSS variable
      const appHeaderHeight = Number.parseInt(
        getComputedStyle(document.documentElement).getPropertyValue("--header-height") || "0",
        10,
      );

      // Add toolbar height only when toolbar is visible
      const adjustment = appHeaderHeight + (toolbarVisible ? toolbarHeight : 0);

      return adjustment;
    }, [isQuickView, toolbarVisible, toolbarHeight]);

    return (
      <StickyListContext.Provider value={itemData}>
        <AutoSizerTable
          ref={listRef}
          totalCount={totalCount}
          loadMore={loadMore}
          isItemLoaded={isItemLoaded}
          itemData={itemData}
          itemSize={itemSize}
          initialScrollOffset={initialScrollOffset}
          className={tableCN.elem("auto-size").mod({ "quick-view": isQuickView }).toClassName()}
          onScroll={onScroll}
          heightAdjustment={heightAdjustment}
          {...rest}
        >
          {ItemWrapper}
        </AutoSizerTable>
      </StickyListContext.Provider>
    );
  }),
);

StickyList.displayName = "StickyList";

const innerElementType = forwardRef(({ children, ...rest }, ref) => {
  return (
    <StickyListContext.Consumer>
      {({ stickyItems, stickyItemsHeight, StickyComponent, headerTopOffset, isQuickView, toolbarHeight }) => {
        // Ensure top position is always between 0 and toolbarHeight in QuickView
        const topPosition = isQuickView ? Math.max(0, Math.min(toolbarHeight, headerTopOffset ?? 0)) : 0;

        // In QuickView mode, children[0] is the toolbar, children[1+] are data rows
        const childrenArray = Array.isArray(children) ? children : children ? [children] : [];
        const toolbar = isQuickView && childrenArray.length > 0 ? childrenArray[0] : null;
        const bodyRows = isQuickView && childrenArray.length > 0 ? childrenArray.slice(1) : children;

        return (
          <div ref={ref} {...rest}>
            {stickyItems.map((index) => (
              <StickyComponent
                className={tableCN.elem("sticky-header").toClassName()}
                key={index}
                index={index}
                style={{
                  height: stickyItemsHeight[index],
                  top: topPosition,
                }}
              />
            ))}

            {isQuickView ? (
              <>
                {toolbar}
                <div className={tableCN.elem("body-rows").toClassName()}>{bodyRows}</div>
              </>
            ) : (
              children
            )}
          </div>
        );
      }}
    </StickyListContext.Consumer>
  );
});
